class LagerException extends Exception {
  private int fachNr = -1;

  public LagerException() {}
  public LagerException(String s) { super(s); }
  public LagerException(String s, int fachNr) { super(s); this.fachNr = fachNr; }

  public int getFachNr() { return fachNr; }
}

class Lager {
  private int[] bestand = {5, 0, 7};

  public void entnehmen(int fach) throws LagerException {
    if (bestand[fach] == 0) {
      throw new LagerException("Fach ist leer", fach);
    }
    bestand[fach]--;
    System.out.println("entnommen aus Fach " + fach);
  }

  public static void main(String[] args) {
    Lager l = new Lager();
    try {
      l.entnehmen(0);
      l.entnehmen(1);
      l.entnehmen(2);
    }
    catch (LagerException e) {
      System.out.println(e.getMessage() + " (Nr. " + e.getFachNr() + ")");
    }
    finally {
      System.out.println("Lagerlauf beendet");
    }
  }
}

