class Auswerter {

  public int sicherTeilen(int a, int b) {
    try {
      return a / b;
    }
    catch (ArithmeticException e) {
      System.out.println("Division durch 0!");
      return 0;
    }
  }

  public int summeAusTexten(String[] texte) {
    int summe = 0;
    for (int i = 0; i < texte.length; i++) {
      try {
        summe = summe + Integer.parseInt(texte[i]);
      }
      catch (NumberFormatException e) {
        System.out.println("ungueltig: " + texte[i]);
      }
    }
    return summe;
  }

  public static void main(String[] args) {
    Auswerter a = new Auswerter();
