import java.io.File;
import java.util.Scanner;

class WoerterLader {
  private static final int MAX_WORDS = 10;
  private String[] words = null;
  private int anzahl = 0;

  public void laden(String dateiname) {
    int len = 0;
    try {
      words = new String[MAX_WORDS];
      Scanner scanner = new Scanner(new File(dateiname));
      while (scanner.hasNextLine() && len < MAX_WORDS) {
        words[len] = scanner.nextLine();
        len++;
      }
      scanner.close();
    }
    catch (java.io.IOException e) {
      len = 3;
      words = new String[len];
      words[0] = "worse";
      words[1] = "worth";
      words[2] = "words";
      System.out.println("Datei fehlt - benutze Backup");
    }
    finally {
      anzahl = len;
      System.out.println("geladen: " + len);
    }
  }

  public String wort(int i) throws WortException {
    if (i < 0 || i >= anzahl) {
      throw new WortException("kein Wort an Position " + i);
    }
    return words[i];
  }

  public static void main(String[] args) {
    WoerterLader w = new WoerterLader();
    w.laden("gibtesnicht.txt");
    try {
      System.out.println(w.wort(1));
      System.out.println(w.wort(7));
    }
    catch (WortException e) {
      System.out.println("Fehler: " + e.getMessage());
    }
  }
}

class WortException extends Exception {
  public WortException(String s) { super(s); }
}

